#!/bin/sh
# Build app.js: one plain browser module at the project root.
#
# Why this exists. The uploaded zip is served straight from the repo root by
# GitHub Pages, and that server will not compile TypeScript. So the page the
# owner opens must reference a finished JavaScript file, and that file must sit
# next to index.html. Run this after changing anything in src/, then re-zip.
set -e

cd "$(dirname "$0")/.."

export PATH="$HOME/.bun/bin:$PATH"

bun build src/main.ts \
  --target=browser \
  --format=esm \
  --minify \
  --banner '// Generated by tools/build-app.sh from src/. Do not hand-edit.' \
  --outfile=app.js

echo "built app.js ($(wc -c < app.js) bytes)"
